/* ---- END GENERATED NAME MAP ---- */

/* The name map's lookup. Rows are grouped by `from` in byte order
   (the order the generator wrote them), a group runs most conditions
   first, and the first row whose conditions all hold answers the
   entry: a row with no conditions is the name's own default and
   sits last. Anything the table does not answer keeps its name —
   the reference's answer for a block it does not rename. */

static int name_cmp_from(const char *lit, const char *name, size_t len)
{
    size_t n = strlen(lit);
    size_t m = (n < len) ? n : len;
    int c = (m > 0) ? memcmp(lit, name, m) : 0;
    if (c != 0) return c;
    if (n == len) return 0;
    return (n < len) ? -1 : 1;
}

static bool name_value_matches(const char *sval, int32_t ival,
                               const McmeTag *v)
{
    if (v == NULL) return false;
    if (sval != NULL) {
        size_t vl = 0;
        const char *s = string_value(v, &vl);
        return s != NULL && vl == strlen(sval)
            && memcmp(s, sval, vl) == 0;
    }
    switch (v->type) {
    case MCME_TAG_Byte:
    case MCME_TAG_Short:
    case MCME_TAG_Int:
    case MCME_TAG_Long:
        return mcme_nbt_int_or(v, 0) == ival;
    default:
        return false;
    }
}

/* NULL-safe compare for the generated tables' optional string
   conditions. */
static bool str_same(const char *a, const char *b)
{
    if (a == NULL || b == NULL) return a == b;
    return strcmp(a, b) == 0;
}

/* The state map's row condition (D27), tag-type strict the way the
   reference is: the value must carry the spec's own tag type and the
   row's own value. The name map's numeric path above is looser —
   D17 shipped it so, and this does not inherit that. */
static bool state_value_matches(uint8_t vtype, int32_t ival,
                                const char *sval, const McmeTag *v)
{
    if (v == NULL || (int)v->type != (int)vtype) return false;
    if (vtype == MCME_TAG_String) {
        size_t vl = 0;
        const char *s = string_value(v, &vl);
        return s != NULL && vl == strlen(sval)
            && memcmp(s, sval, vl) == 0;
    }
    return mcme_nbt_int_or(v, 0) == ival;
}

/* One property from one row: Java's properties are strings whatever
   type the reference's own answer carries. Later puts on the same
   key replace in place, which is the composition order (table
   order, rescues last) the rows were measured under. */
static bool state_prop_put(McmeArena *arena, McmeTag *props,
                           const char *to, const char *val,
                           size_t *kept)
{
    McmeTag *sv = mcme_nbt_new(arena, MCME_TAG_String);
    if (sv == NULL
            || !mcme_nbt_set_string(arena, sv, val, strlen(val))
            || !mcme_nbt_compound_put(arena, props, to, strlen(to),
                                      sv)) {
        return false;
    }
    ++*kept;
    return true;
}

static void resolve_java_name(const char *name, size_t name_len,
                              const McmeTag *states,
                              const char **out, size_t *out_len)
{
    size_t rows = sizeof kNameMap / sizeof kNameMap[0];
    size_t lo = 0, hi = rows;
    while (lo < hi) {                       /* lower bound of name */
        size_t mid = lo + (hi - lo) / 2;
        if (name_cmp_from(kNameMap[mid].from, name, name_len) < 0)
            lo = mid + 1;
        else
            hi = mid;
    }
    for (size_t i = lo; i < rows
             && name_cmp_from(kNameMap[i].from, name, name_len) == 0;
         ++i) {
        const struct NameMapRow *r = &kNameMap[i];
        if (r->state == NULL) {             /* the name's default */
            *out = r->to;
            *out_len = strlen(r->to);
            return;
        }
        if (!name_value_matches(r->sval, r->ival,
                                mcme_nbt_get(states, r->state))) {
            continue;
        }
        if (r->state2 != NULL
                && !name_value_matches(r->sval2, r->ival2,
                                       mcme_nbt_get(states,
                                                    r->state2))) {
            continue;
        }
        *out = r->to;
        *out_len = strlen(r->to);
        return;
    }
}

/* ---- BEGIN GENERATED LEGACY MAP ----
 * The pre-1.9 palette's `{name, val}` answers (D24): amulet's
 * loader spells a val-only entry `block_data` and translates it
 * through the last pre-1.13 spec (min(world, 1.12.x) -> Bedrock
 * 1.12.0 -> Java 1.20.0), so every row below is that rule's own
 * answer, enumerated over the byte domain -128..255 for each of
 * the 328 names the 1.12 tables hold. Five names decode by
 * formula rather than table (kelp's age, sapling's type/stage,
 * tnt's unstable, noteblock's constant note, lava_cauldron's);
 * each carries one default row for every val the explicit rows
 * do not claim, verified across the int32 range. An entry
 * neither table holds keeps its name and no properties — the
 * reference's own pass-through with block_data dropped by the
 * unknown-block policy. Sorted by name (byte order) then val;
 * the lookup binary searches, and tools/ref_convert.py re-pins
 * every row against the reference on every battery run. */
struct LegacyProp {
    const char *key;
    const char *val;
};

struct LegacyRow {
    const char *from;      /* the entry's `name`                   */
    int32_t     val;       /* the entry's `val`                    */
    const char *to;        /* Java's Name                          */
    size_t      nprops;
    struct LegacyProp props[7];
};

struct LegacyDefault {
    const char *from;
    const char *to;
    size_t      nprops;
    struct LegacyProp props[7];
};

